function bindStates(country_id) {
    var dispstateval = document.getElementById("ctl00_HomePageContent_hdnState").value;
    //alert(dispstateval);
    var option_str = document.getElementById('ctl00_HomePageContent_ddlDispensaryState');   //ctl00_HomePageContent_ddlDispensaryState  name=ctl00$HomePageContent$ddlDispensaryState
    var x, i = 0;
    for (x in s) {
        option_str.options[i++] = new Option(s[x], s[x]);
    }

    if (dispstateval > 0) {
        option_str.options[dispstateval].selected = true;
        dispDistricts('ctl00_HomePageContent_ddlDispensaryDistrict', dispstateval);
        if (document.getElementById('ctl00_HomePageContent_hdnDistrict').value != "")
            dispDispIMP('', document.getElementById('ctl00_HomePageContent_hdnDistrict').value, 'postback')
    }
}
function dispDistricts(sample_id, sample_index) {

    if (document.getElementById("ctl00_HomePageContent_hdnState").value != sample_index.toString()) {
        document.getElementById("ctl00_HomePageContent_hdnState").value = sample_index.toString();
        document.getElementById("ctl00_HomePageContent_hdnDistrict").value = "";
    }
    var dispdistval = document.getElementById("ctl00_HomePageContent_hdnDistrict").value;
    inx = sample_index.toString();

    var option_str = document.getElementById('ctl00_HomePageContent_ddlDispensaryDistrict');
    option_str.options.length = 0;

    var disp = document.getElementById('ctl00_HomePageContent_ctrlTextDispensary');
    var dispAdd = document.getElementById('ctl00_HomePageContent_txtDispensaryAddress');
    disp.options.length = 0; dispAdd.value = "";

    var x, i = 0; sample_index;

    var drr = d[sample_index].split(",");
    for (x in drr) {

        option_str.options[i++] = new Option(drr[x], drr[x]);
    }

    if (dispdistval > 0)
        option_str.options[dispdistval].selected = true;
}
function dispDispIMP(did, dindex, sample3add_id) {
    debugger;
    if (document.getElementById("ctl00_HomePageContent_hdnDistrict").value != dindex.toString()) {
        document.getElementById("ctl00_HomePageContent_hdnDistrict").value = dindex.toString();
        document.getElementById("ctl00_HomePageContent_hdnImpname").value = "";
        document.getElementById("ctl00_HomePageContent_hdnImpaddress").value = "";
    }
    var option_str = document.getElementById('ctl00_HomePageContent_ctrlTextDispensary');
    var option_stradd = document.getElementById('ctl00_HomePageContent_txtDispensaryAddress');
    option_str.options.length = 0;
    stval = document.getElementById("ctl00_HomePageContent_hdnState").value * 1000 + 1;

    inx1 = stval.toString().concat(document.getElementById("ctl00_HomePageContent_hdnDistrict").value.toString());
    var x, i = 0;
    option_stradd.value = "";
    var optRadList = document.getElementById('ctl00_HomePageContent_ctrlRBDispensaryIMP');
    if (optRadList.rows[0].cells[0].firstChild.checked) {
        var sample3_arr = di[inx1].split("|");

        for (x in sample3_arr) {
            var indx = sample3_arr[x].indexOf("-");
            option_str.options[i++] = new Option(sample3_arr[x].substr(indx + 1, sample3_arr[x].length), sample3_arr[x].substr(0, indx));
        }
    }
    else {
        var sample5_arr = ii[inx1].split("|");
        for (x in sample5_arr) {
            var indx = sample5_arr[x].indexOf("-");
            option_str.options[i++] = new Option(sample5_arr[x].substr(indx + 1, sample5_arr[x].length), sample5_arr[x].substr(0, indx));
        }
    }
    if (document.getElementById("ctl00_HomePageContent_hdnImpname").value > 0 && sample3add_id == 'postback') {
        var dispVal = document.getElementById("ctl00_HomePageContent_hdnImpname").value;
        var dispAddr = document.getElementById("ctl00_HomePageContent_hdnImpaddress").value;
        var ddlDisp = document.getElementById('ctl00_HomePageContent_ctrlTextDispensary');
        ddlDisp.options[dispVal].selected = true;
        var txtAddr = document.getElementById('ctl00_HomePageContent_txtDispensaryAddress');
        txtAddr.value = dispAddr;
    }
}
function dispDispIMPAddress(dad, dandex) {
    if (document.getElementById("ctl00_HomePageContent_hdnImpname").value != dandex.toString()) {
        document.getElementById("ctl00_HomePageContent_hdnImpname").value = dandex.toString();
        document.getElementById("ctl00_HomePageContent_hdnImpaddress").value = "";
    }
    var option_str = document.getElementById('ctl00_HomePageContent_txtDispensaryAddress');
    option_str.value = "";
    var x, i = 0;
    var optRadList = document.getElementById('ctl00_HomePageContent_ctrlRBDispensaryIMP');
    if (optRadList.rows[0].cells[0].firstChild.checked) {
        var sample4_arr = da[inx1].split("|");
        option_str.value = sample4_arr[dandex];
        document.getElementById("ctl00_HomePageContent_hdnImpaddress").value = sample4_arr[dandex];
    }
    else {
        var sample6_arr = ia[inx1].split("|");
        option_str.value = sample6_arr[dandex];
        document.getElementById("ctl00_HomePageContent_hdnImpaddress").value = sample6_arr[dandex];
    }
}
function changeRads(did) {
    var option_str = document.getElementById('ctl00_HomePageContent_ctrlTextDispensary');
    var option_stradd = document.getElementById('ctl00_HomePageContent_txtDispensaryAddress');
    option_str.options.length = 0;
    option_stradd.value = "";
    if (inx > 0 && hdnDistrict.value != "") {
        dispDispIMP(option_str, document.getElementById('ctl00_HomePageContent_hdnDistrict').value, option_stradd)
    }
}
function saveDispIMP() {
    var e = document.getElementById('ctl00_HomePageContent_ctrlTextDispensary');
    document.getElementById('ctl00_HomePageContent_hdnDisIMP').value = e.options[e.selectedIndex].value;

    return true;
}       